// Build the operator console (packages/inspector-ui) and embed its static assets into @mayura/server, which serves
// them same-origin under a strict CSP. The server package stays runtime-neutral: no filesystem reads, no build tools.
//   node scripts/inspector-bundle.mjs           rebuild and rewrite packages/server/src/inspector-bundle.ts
//   node scripts/inspector-bundle.mjs --check   fail if the console sources changed since the bundle was built (CI)
//   node scripts/inspector-bundle.mjs --verify  also rebuild and require byte-identical assets (same platform only)
// The CI check compares a digest of the console's sources (line endings normalized), not build output: native
// bundlers are not guaranteed to emit byte-identical files on every operating system.
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { createHash } from 'node:crypto';
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const workspace = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const ui = join(workspace, 'packages', 'inspector-ui');
const target = join(workspace, 'packages', 'server', 'src', 'inspector-bundle.ts');

/** Every input that shapes the bundle: the console, the client it bundles and this script. */
async function sourceDigest() {
  const files = [];
  const walk = async directory => {
    for (const entry of await readdir(directory, { withFileTypes: true })) {
      const path = join(directory, entry.name);
      if (entry.isDirectory()) await walk(path); else files.push(path);
    }
  };
  for (const file of ['index.html', 'package.json', 'tsconfig.json', 'vite.config.ts']) files.push(join(ui, file));
  await walk(join(ui, 'src'));
  files.push(join(workspace, 'packages', 'client', 'package.json')); await walk(join(workspace, 'packages', 'client', 'src'));
  files.push(fileURLToPath(import.meta.url));
  const hash = createHash('sha256');
  for (const file of files.map(path => relative(workspace, path).replaceAll('\\', '/')).sort()) {
    let text = (await readFile(join(workspace, file), 'utf8')).replaceAll('\r\n', '\n');
    // A release sets every package's version; nothing in the console reads it, so it does not make the bundle stale.
    if (file.endsWith('package.json')) { const manifest = JSON.parse(text); delete manifest.version; text = JSON.stringify(manifest); }
    hash.update(`${file}\0`).update(text).update('\0');
  }
  return hash.digest('hex');
}

async function build() {
  await promisify(execFile)(process.execPath, [join(workspace, 'node_modules', 'vite', 'bin', 'vite.js'), 'build', '--logLevel', 'error'], { cwd: ui, windowsHide: true, maxBuffer: 16 * 1_048_576 });
  const assets = {};
  for (const [path, file, type] of [['/inspector', 'index.html', 'text/html; charset=utf-8'], ['/inspector/app.js', 'app.js', 'text/javascript; charset=utf-8'], ['/inspector/app.css', 'app.css', 'text/css; charset=utf-8']]) {
    const body = await readFile(join(ui, 'dist', file), 'utf8');
    assert(!/<script(?![^>]*\bsrc=)[^>]*>/i.test(body) || file !== 'index.html', 'The console HTML must not contain inline scripts.');
    if (file === 'index.html') assert.equal(body.split('__MAYURA_STYLE_NONCE__').length, 2, 'The console HTML must carry exactly one style nonce placeholder.');
    assets[path] = { type, body };
  }
  return assets;
}

const render = (assets, sources) => {
  const digest = createHash('sha256').update(JSON.stringify(assets)).digest('hex');
  return { digest, source: `// Generated by scripts/inspector-bundle.mjs from packages/inspector-ui. Do not edit; rebuild instead.
// sha256:${digest}
// sources:${sources}
export const INSPECTOR_BUNDLE_DIGEST = '${digest}';
export const INSPECTOR_ASSETS: Readonly<Record<string, { readonly type: string; readonly body: string }>> = Object.freeze(${JSON.stringify(assets)});
` };
};

const sources = await sourceDigest();
if (process.argv.includes('--check') || process.argv.includes('--verify')) {
  const current = await readFile(target, 'utf8').catch(() => '');
  const recorded = /^\/\/ sources:([a-f0-9]{64})$/m.exec(current)?.[1];
  assert.equal(recorded, sources, 'The operator console sources changed; run node scripts/inspector-bundle.mjs and commit packages/server/src/inspector-bundle.ts.');
  if (process.argv.includes('--verify')) assert.equal(current.replaceAll('\r\n', '\n'), render(await build(), sources).source, 'A fresh build differs from the committed console bundle.');
  console.log(JSON.stringify({ status: 'unchanged', sources }));
} else {
  const { digest, source } = render(await build(), sources);
  await writeFile(target, source);
  console.log(JSON.stringify({ status: 'written', digest, sources, bytes: source.length }));
}
